import{_ as a}from"./chunks/plugin-vue_export-helper.DlAUqK2U.js";import{c as e,o as d,af as r}from"./chunks/mermaid.DEOxUarQ.js";import"./chunks/cytoscape.C2CwDKBM.js";import"./chunks/dayjs.C32PoDnw.js";const x=JSON.parse('{"title":"Codex 生态学习导航","description":"","frontmatter":{},"headers":[],"relativePath":"zh/products/ai-coding/codex/index.md","filePath":"zh/products/ai-coding/codex/index.md","lastUpdated":1787048027000}'),o={name:"zh/products/ai-coding/codex/index.md"};function n(s,t,h,l,c,p){return d(),e("div",null,[...t[0]||(t[0]=[r(`<h1 id="codex-生态学习导航" tabindex="-1">Codex 生态学习导航 <a class="header-anchor" href="#codex-生态学习导航" aria-label="Permalink to &quot;Codex 生态学习导航&quot;">​</a></h1><blockquote><p>Codex 是 OpenAI 的编程 Agent。它和 ChatGPT 的 Chat、Work 一起住在同一套网页 / 桌面应用里，再加 CLI、IDE 和云端。本页是全家桶地图：先看清产品树，再按「我要做什么」落到具体页。</p><p>官方文档在 <code>learn.chatgpt.com/docs</code>。旧地址 <code>developers.openai.com/codex/*</code> 会 308 过去。</p></blockquote><h2 id="产品全景图" tabindex="-1">产品全景图 <a class="header-anchor" href="#产品全景图" aria-label="Permalink to &quot;产品全景图&quot;">​</a></h2><p>OpenAI 这一侧不是「一个 CLI」，而是同一账号下的几层产品。2026-07-09 起，独立 Codex 桌面应用并入 <a href="https://learn.chatgpt.com/docs/app" target="_blank" rel="noreferrer">ChatGPT 桌面应用</a>：里面同时有 Chat、Work、Codex。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>OpenAI 编程与智能代理生态</span></span>
<span class="line"><span>├── ChatGPT Chat（对话智能）— 问答、写作、比方案</span></span>
<span class="line"><span>│   ├── 网页 chatgpt.com</span></span>
<span class="line"><span>│   ├── 桌面应用（macOS / Windows；Linux 预览）</span></span>
<span class="line"><span>│   └── 手机（含 Remote 接着本机会话）</span></span>
<span class="line"><span>├── ChatGPT Work（知识工作代理）— 做到可审的成品</span></span>
<span class="line"><span>│   ├── 云端（网页默认；关电脑也能跑）</span></span>
<span class="line"><span>│   ├── 本机（桌面 Work locally：本地文件 / 应用）</span></span>
<span class="line"><span>│   ├── 定期任务 Scheduled</span></span>
<span class="line"><span>│   ├── 插件 Plugins（Slack / Drive / SharePoint…）</span></span>
<span class="line"><span>│   └── Sites（托管网页 / 内部工具，公开测试）</span></span>
<span class="line"><span>├── Codex（编程代理）— 写代码、调试、提 PR</span></span>
<span class="line"><span>│   ├── 终端 CLI            — 最灵活，可进 CI</span></span>
<span class="line"><span>│   ├── IDE 扩展            — 编辑器上下文、行内 diff</span></span>
<span class="line"><span>│   ├── 桌面应用里的 Codex   — 可视化 diff、PR 侧栏、多仓库</span></span>
<span class="line"><span>│   ├── 网页 chatgpt.com/codex</span></span>
<span class="line"><span>│   ├── Cloud               — 隔离环境，可并行、可从 GitHub / Linear / Slack 派活</span></span>
<span class="line"><span>│   ├── Remote              — 手机接着一台已连接电脑</span></span>
<span class="line"><span>│   └── Security            — 插件 + CLI/SDK + 云端扫描</span></span>
<span class="line"><span>├── Chrome 扩展             — Work / Codex 驱动已登录的 Chrome 标签</span></span>
<span class="line"><span>└── 已下线：Atlas 独立浏览器</span></span>
<span class="line"><span>    └── 官方于 2026-08-09 停止；浏览代理能力并入 ChatGPT / Codex</span></span></code></pre></div><p>桌面 Codex 就是 ChatGPT 桌面应用里的 Codex 视图——入口写在 <a href="./codex-ai.html">产品线</a> 和 <a href="./chatgpt-work.html#桌面上-work-和-codex-怎么选">Work 与 Codex 对照</a>，不再单独成页。<strong>Pets</strong> 是可选的动画伴侣，用来跟会话状态；没有教程。</p><p>这是<strong>一套配置、一个 Agent 内核</strong>，入口不同。CLI 里学会的沙箱、审批和 <code>AGENTS.md</code>，在 IDE / 桌面 Codex / Cloud 同样生效。Work 和 Codex <strong>共用用量额度</strong>。</p><h3 id="快速决策-我要做什么" tabindex="-1">快速决策：我要做什么？ <a class="header-anchor" href="#快速决策-我要做什么" aria-label="Permalink to &quot;快速决策：我要做什么？&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>我要做什么？</span></span>
<span class="line"><span>├── 写代码 / 调试 / 重构 / 提 PR</span></span>
<span class="line"><span>│   └── → Codex</span></span>
<span class="line"><span>│       ├── 在终端 / CI？→ CLI（codex / codex exec）</span></span>
<span class="line"><span>│       ├── 在编辑器里对着当前文件？→ [IDE 扩展](./codex-ide)</span></span>
<span class="line"><span>│       ├── 要可视化 diff / PR 侧栏？→ 桌面应用里的 Codex（[产品线](./codex-ai)）</span></span>
<span class="line"><span>│       ├── 没带电脑 / 要并行多试几次？→ [Codex Cloud](./codex-cloud)</span></span>
<span class="line"><span>│       ├── 手机遥控、电脑还醒着？→ [Remote](./codex-remote)</span></span>
<span class="line"><span>│       └── 在 GitHub / Linear / Slack 里派活？→ Cloud + 官方集成</span></span>
<span class="line"><span>├── 问答 / 写作 / 比方案 / 把设计谈清楚</span></span>
<span class="line"><span>│   └── → ChatGPT Chat（网页、桌面或手机）</span></span>
<span class="line"><span>│       ├── 需要持久主题上下文？→ Project</span></span>
<span class="line"><span>│       ├── 需要语音？→ 桌面 / iOS Voice</span></span>
<span class="line"><span>│       └── 谈定后要落地仓库？→ 写成任务说明，交给 Codex</span></span>
<span class="line"><span>├── 要一份能打开的 PPT / 表 / 简报 / 定期汇报</span></span>
<span class="line"><span>│   └── → ChatGPT Work</span></span>
<span class="line"><span>│       ├── 源材料在网盘 / Slack？→ 装插件，提示词里 @它</span></span>
<span class="line"><span>│       ├── 要动本机文件或应用？→ 桌面 Work locally</span></span>
<span class="line"><span>│       ├── 关电脑也要跑？→ Cloud / 网页 Work</span></span>
<span class="line"><span>│       └── 要托管一个内部页？→ [Sites](./sites)（先 save version，再 deploy）</span></span>
<span class="line"><span>├── 在我有权评估的仓库里找 / 确认 / 修漏洞</span></span>
<span class="line"><span>│   └── → [Codex Security](./codex-security)（插件 / CLI / Cloud）</span></span>
<span class="line"><span>├── 要动我已经登录的 Chrome 页面</span></span>
<span class="line"><span>│   └── → [Chrome 扩展](./codex-chrome)（\`@Chrome\`）；localhost → \`@Browser\`</span></span>
<span class="line"><span>├── 接入外部服务</span></span>
<span class="line"><span>│   └── → 分清两层</span></span>
<span class="line"><span>│       ├── 日常 SaaS（Drive / Slack / Notion 类）→ Work / Chat 的 Plugins</span></span>
<span class="line"><span>│       └── 仓库、CI、自建工具 → Codex MCP（见项目集成）</span></span>
<span class="line"><span>└── 还在找 Atlas 浏览器？</span></span>
<span class="line"><span>    └── → 独立 Atlas 已停。用桌面内置浏览器、Chrome 扩展或 Work 的 Cloud Browser</span></span></code></pre></div><h2 id="核心概念速览" tabindex="-1">核心概念速览 <a class="header-anchor" href="#核心概念速览" aria-label="Permalink to &quot;核心概念速览&quot;">​</a></h2><p>完整定义在 <a href="./codex-glossary.html">术语表</a>。</p><table tabindex="0"><thead><tr><th>概念</th><th>一句话</th><th>出现位置</th></tr></thead><tbody><tr><td><strong>Chat / Work / Codex</strong></td><td>同一应用里的三种工作方式：聊、做完、写代码</td><td>全局</td></tr><tr><td><strong>沙箱</strong></td><td>文件和网络的硬边界</td><td>Codex</td></tr><tr><td><strong>审批策略</strong></td><td>行动前要不要问你</td><td>Codex</td></tr><tr><td><strong><code>AGENTS.md</code></strong></td><td>每次运行自动加载的项目简报</td><td>Codex 全入口</td></tr><tr><td><strong>MCP / Plugins</strong></td><td>接到仓库外的工具；Work 侧叫插件</td><td>Codex / Work</td></tr><tr><td><strong>Sites</strong></td><td>ChatGPT 托管网页和应用（公开测试）</td><td><a href="./sites.html">Sites</a></td></tr><tr><td><strong>Codex Cloud</strong></td><td>在托管环境里并行跑编程任务</td><td><a href="./codex-cloud.html">Cloud</a></td></tr><tr><td><strong>IDE 扩展</strong></td><td>编辑器上下文、行内 diff</td><td><a href="./codex-ide.html">IDE</a></td></tr><tr><td><strong>Remote</strong></td><td>手机带一台已连接电脑</td><td><a href="./codex-remote.html">Remote</a></td></tr><tr><td><strong>Codex Security</strong></td><td>找 / 确认 / 修漏洞（插件 + CLI + Cloud）</td><td><a href="./codex-security.html">Security</a></td></tr><tr><td><strong>Chrome 扩展</strong></td><td>驱动已登录的 Chrome 标签</td><td><a href="./codex-chrome.html">Chrome</a></td></tr><tr><td><strong>Atlas</strong></td><td>已下线的独立浏览器，能力并入 ChatGPT / Codex</td><td>历史</td></tr></tbody></table><h2 id="学习路径" tabindex="-1">学习路径 <a class="header-anchor" href="#学习路径" aria-label="Permalink to &quot;学习路径&quot;">​</a></h2><h3 id="第一阶段-分清-chat、work、codex" tabindex="-1">第一阶段：分清 Chat、Work、Codex <a class="header-anchor" href="#第一阶段-分清-chat、work、codex" aria-label="Permalink to &quot;第一阶段：分清 Chat、Work、Codex&quot;">​</a></h3><p>先建立「同一账号、三种工作方式」的心智模型，再碰终端。</p><p><strong>目标</strong>：会切 Chat / Work / Codex，知道套餐含什么、数字去哪查。</p><table tabindex="0"><thead><tr><th>步骤</th><th>内容</th><th>链接</th></tr></thead><tbody><tr><td>1</td><td>产品线：四个 Codex 入口 + 桌面合并</td><td><a href="./codex-ai.html">Codex 产品线</a></td></tr><tr><td>2</td><td>套餐、登录、Chat 和 Codex 怎么配对</td><td><a href="./chatgpt-plus.html">ChatGPT 套餐与访问</a></td></tr><tr><td>3</td><td>Work：可审成品、本地 vs 云端、插件</td><td><a href="./chatgpt-work.html">ChatGPT Work</a></td></tr><tr><td>4</td><td>托管网页 / 内部工具（公开测试）</td><td><a href="./sites.html">Sites</a></td></tr></tbody></table><h3 id="第二阶段-上手-codex-cli" tabindex="-1">第二阶段：上手 Codex CLI <a class="header-anchor" href="#第二阶段-上手-codex-cli" aria-label="Permalink to &quot;第二阶段：上手 Codex CLI&quot;">​</a></h3><p>面向前端工程师的主路径。</p><p><strong>目标</strong>：能在熟悉的仓库里只读跑一次，配好沙箱和 <code>AGENTS.md</code>。</p><table tabindex="0"><thead><tr><th>步骤</th><th>内容</th><th>链接</th></tr></thead><tbody><tr><td>1</td><td>安装 + 登录 + 第一次只读会话</td><td><a href="./codex-cli.html">Codex CLI</a> 第 1–3 步</td></tr><tr><td>2</td><td>TUI 快捷键和斜杠命令</td><td><a href="./codex-cli.html#第-4-步--在-tui-里工作">→ 交互基础</a></td></tr><tr><td>3</td><td><code>sandbox_mode</code> 与 <code>approval_policy</code></td><td><a href="./codex-cli.html#第-6-步--配置">→ 配置</a></td></tr><tr><td>4</td><td><code>/init</code> 写出 <code>AGENTS.md</code></td><td><a href="./codex-cli.html">→ CLI</a> 第 7 步</td></tr><tr><td>5</td><td>日常任务配方</td><td><a href="./codex-cookbook.html">Cookbook</a></td></tr><tr><td>6</td><td>flag / 配置键随手查</td><td><a href="./codex-cheatsheet.html">Cheatsheet</a></td></tr><tr><td>7</td><td>概念记混了查定义</td><td><a href="./codex-glossary.html">术语表</a></td></tr></tbody></table><p>只读两页：先 <a href="./codex-cli.html">CLI</a>，再钉住 <a href="./codex-cheatsheet.html">速查表</a>。</p><h3 id="第三阶段-接到真实项目和-ci" tabindex="-1">第三阶段：接到真实项目和 CI <a class="header-anchor" href="#第三阶段-接到真实项目和-ci" aria-label="Permalink to &quot;第三阶段：接到真实项目和 CI&quot;">​</a></h3><p><strong>目标</strong>：提交一份有效的 <code>AGENTS.md</code> 和 <code>.codex/config.toml</code>，CI 里用 <code>codex exec</code>。</p><table tabindex="0"><thead><tr><th>步骤</th><th>内容</th><th>链接</th></tr></thead><tbody><tr><td>1</td><td>指令链、信任、项目配置</td><td><a href="./integration.html">项目集成</a></td></tr><tr><td>2</td><td>MCP、Hooks、Subagents</td><td><a href="./integration.html#mcp-服务器">→ 集成</a></td></tr><tr><td>3</td><td><code>codex exec</code> + GitHub Action</td><td><a href="./integration.html#ci-集成">→ CI</a></td></tr></tbody></table><h3 id="第四阶段-云端、托管评审、远程" tabindex="-1">第四阶段：云端、托管评审、远程 <a class="header-anchor" href="#第四阶段-云端、托管评审、远程" aria-label="Permalink to &quot;第四阶段：云端、托管评审、远程&quot;">​</a></h3><p><strong>目标</strong>：会为仓库建 Cloud 环境；知道托管评审用哪颗模型。</p><table tabindex="0"><thead><tr><th>步骤</th><th>内容</th><th>链接</th></tr></thead><tbody><tr><td>1</td><td>何时用 Cloud、<code>codex cloud exec</code></td><td><a href="./codex-cloud.html">Codex Cloud</a></td></tr><tr><td>2</td><td>从 GitHub / Linear / Slack 派任务</td><td><a href="./codex-cloud.html">Cloud</a> · 官方 <a href="https://learn.chatgpt.com/docs/cloud" target="_blank" rel="noreferrer">cloud 文档</a></td></tr><tr><td>3</td><td>手机批已连接主机上的任务</td><td><a href="./codex-remote.html">Remote</a></td></tr><tr><td>4</td><td>编辑器上下文和原地评审</td><td><a href="./codex-ide.html">IDE</a></td></tr><tr><td>5</td><td>本机 <code>/review</code> vs 托管 code review</td><td><a href="https://learn.chatgpt.com/docs/code-review" target="_blank" rel="noreferrer">Code review</a></td></tr><tr><td>6</td><td>第一次安全扫描（插件 / CLI / Cloud）</td><td><a href="./codex-security.html">Security</a></td></tr></tbody></table><h3 id="第五阶段-work-自动化-知识工作" tabindex="-1">第五阶段：Work 自动化（知识工作） <a class="header-anchor" href="#第五阶段-work-自动化-知识工作" aria-label="Permalink to &quot;第五阶段：Work 自动化（知识工作）&quot;">​</a></h3><p>轴 B：Work 更靠近非编程日常，排在 Codex 主路径之后。前端仍然会用它写周报、出 Sites、盯 Slack。</p><table tabindex="0"><thead><tr><th>步骤</th><th>内容</th><th>链接</th></tr></thead><tbody><tr><td>1</td><td>Work 定位与三个官方起步任务</td><td><a href="./chatgpt-work.html">ChatGPT Work</a></td></tr><tr><td>2</td><td>本地 vs 云端、定期任务</td><td><a href="./chatgpt-work.html#2-选本地还是云端">→ Work</a></td></tr><tr><td>3</td><td>插件与 Sites 边界</td><td><a href="./chatgpt-work.html#插件接到你真正在用的工具">→ Work</a> · <a href="./sites.html">Sites</a></td></tr></tbody></table><h2 id="功能速查表" tabindex="-1">功能速查表 <a class="header-anchor" href="#功能速查表" aria-label="Permalink to &quot;功能速查表&quot;">​</a></h2><h3 id="chatgpt-chat" tabindex="-1">ChatGPT Chat <a class="header-anchor" href="#chatgpt-chat" aria-label="Permalink to &quot;ChatGPT Chat&quot;">​</a></h3><table tabindex="0"><thead><tr><th>功能</th><th>用途</th><th>去哪读</th></tr></thead><tbody><tr><td>Chat</td><td>问答、草稿、把设计谈清楚</td><td><a href="./chatgpt-plus.html#chatgpt-chat-对话智能">套餐与访问</a></td></tr><tr><td>Projects</td><td>同一主题下的会话、文件、指令</td><td><a href="https://learn.chatgpt.com/docs/projects" target="_blank" rel="noreferrer">Projects</a></td></tr><tr><td>Voice</td><td>桌面 / iOS 语音，可对着文件和 Project</td><td><a href="https://learn.chatgpt.com/docs/features/voice" target="_blank" rel="noreferrer">Voice</a></td></tr><tr><td>Computer History</td><td>macOS 活动时间线 → 记忆（默认关）</td><td><a href="https://learn.chatgpt.com/docs/customization/computer-history" target="_blank" rel="noreferrer">Computer History</a></td></tr><tr><td>Library</td><td>已保存文件再次引用</td><td><a href="./chatgpt-plus.html">套餐与访问</a></td></tr></tbody></table><h3 id="chatgpt-work" tabindex="-1">ChatGPT Work <a class="header-anchor" href="#chatgpt-work" aria-label="Permalink to &quot;ChatGPT Work&quot;">​</a></h3><table tabindex="0"><thead><tr><th>功能</th><th>用途</th><th>文档</th></tr></thead><tbody><tr><td>可审成品</td><td>PPT / 表 / 文档 / PDF</td><td><a href="./chatgpt-work.html">ChatGPT Work</a></td></tr><tr><td>本地 / 云端</td><td>本机文件 vs 关电脑续跑</td><td><a href="./chatgpt-work.html#2-选本地还是云端">ChatGPT Work</a></td></tr><tr><td>插件</td><td>Drive / Slack / SharePoint…</td><td><a href="./chatgpt-work.html#插件接到你真正在用的工具">ChatGPT Work</a></td></tr><tr><td>Sites</td><td>托管网页和应用（公开测试）</td><td><a href="./sites.html">Sites</a></td></tr><tr><td>定期任务</td><td>重复调研、议程、监控</td><td><a href="./chatgpt-work.html#做定期更新">ChatGPT Work</a></td></tr><tr><td>Computer Use</td><td>操作桌面 GUI（macOS / Windows）</td><td><a href="https://learn.chatgpt.com/docs/computer-use" target="_blank" rel="noreferrer">Computer Use</a></td></tr><tr><td>Browser</td><td>桌面内置浏览器或 Work 云端浏览器</td><td><a href="https://learn.chatgpt.com/docs/browser" target="_blank" rel="noreferrer">Browser</a></td></tr><tr><td>Chrome 扩展</td><td>已登录的 Chrome 标签</td><td><a href="./codex-chrome.html">Chrome</a></td></tr></tbody></table><h3 id="codex-核心功能" tabindex="-1">Codex 核心功能 <a class="header-anchor" href="#codex-核心功能" aria-label="Permalink to &quot;Codex 核心功能&quot;">​</a></h3><table tabindex="0"><thead><tr><th>功能</th><th>用途</th><th>文档</th></tr></thead><tbody><tr><td>终端 CLI</td><td>项目目录里交互；CI 用 <code>codex exec</code></td><td><a href="./codex-cli.html">CLI</a></td></tr><tr><td>IDE 扩展</td><td>当前文件 / 选区</td><td><a href="./codex-ide.html">IDE</a></td></tr><tr><td>桌面 Codex</td><td>diff、PR 侧栏、多仓库、Computer Use</td><td><a href="./codex-ai.html">产品线</a></td></tr><tr><td>Web / Cloud</td><td>托管环境、并行、<code>--attempts</code></td><td><a href="./codex-cloud.html">Cloud</a></td></tr><tr><td>Remote</td><td>手机带一台已连接的 Mac / Windows</td><td><a href="./codex-remote.html">Remote</a></td></tr><tr><td>托管评审</td><td>Cloud 上的 code review / QA；合格客户用 GPT-5.6 Sol</td><td><a href="./codex-cloud.html">Cloud</a></td></tr><tr><td>Security</td><td>插件工作台、CLI/SDK、Cloud 扫描</td><td><a href="./codex-security.html">Security</a></td></tr><tr><td><code>AGENTS.md</code></td><td>项目简报</td><td><a href="./integration.html">集成</a></td></tr><tr><td>MCP / Hooks / Skills / Plugins</td><td>扩展面</td><td><a href="./codex-glossary.html">术语表</a></td></tr><tr><td>Codex SDK</td><td>程序化本机线程（TS / Python）</td><td><a href="https://learn.chatgpt.com/docs/codex-sdk" target="_blank" rel="noreferrer">Codex SDK</a></td></tr><tr><td>GitHub Action</td><td><code>openai/codex-action@v1</code> 跑 <code>codex exec</code></td><td><a href="https://learn.chatgpt.com/docs/github-action" target="_blank" rel="noreferrer">GitHub Action</a></td></tr><tr><td>App Server</td><td>富客户端 JSON-RPC / <code>codex --remote</code></td><td><a href="https://learn.chatgpt.com/docs/app-server" target="_blank" rel="noreferrer">App Server</a></td></tr><tr><td>Codex Micro</td><td>Work Louder 硬件键，跟桌面会话</td><td><a href="https://learn.chatgpt.com/docs/features/codex-micro" target="_blank" rel="noreferrer">Codex Micro</a></td></tr><tr><td>实战配方</td><td>重构、测试、排错</td><td><a href="./codex-cookbook.html">Cookbook</a></td></tr><tr><td>配置速查</td><td>flag、键、决策表</td><td><a href="./codex-cheatsheet.html">Cheatsheet</a></td></tr></tbody></table><h2 id="模型参考" tabindex="-1">模型参考 <a class="header-anchor" href="#模型参考" aria-label="Permalink to &quot;模型参考&quot;">​</a></h2><p>截至 2026 年 8 月，官方推荐的 5.6 家族是 <strong>Sol / Terra / Luna</strong>。默认 <strong>Power</strong> 使用中等推理的 Sol。名称会变，以 <a href="https://learn.chatgpt.com/docs/models" target="_blank" rel="noreferrer">Models</a> 为准。</p><table tabindex="0"><thead><tr><th>模型</th><th>官方定位</th><th>本教程怎么用</th></tr></thead><tbody><tr><td>GPT-5.6 Sol</td><td>旗舰：复杂编程、Computer Use、研究、安全</td><td>Cloud 托管评审 / QA 对合格客户自动用 Sol</td></tr><tr><td>GPT-5.6 Terra</td><td>能力与成本折中</td><td>日常本地 / 网页任务</td></tr><tr><td>GPT-5.6 Luna</td><td>最快、最便宜</td><td>小改动、子代理、高通量</td></tr><tr><td>GPT-5.3-Codex-Spark</td><td>ChatGPT Pro 研究预览</td><td>仅 Pro；见定价页</td></tr></tbody></table><p><code>config.toml</code> 示例仍写 <code>model = &quot;gpt-5.6&quot;</code>。Chat 里的 Sol 滑块<strong>不</strong>改变 Work / Codex 的模型行为。GPT-5.4 / 5.4 mini 将于 2026-08-31 从 ChatGPT 登录的 Codex 下线。</p><h2 id="诚实的限制" tabindex="-1">诚实的限制 <a class="header-anchor" href="#诚实的限制" aria-label="Permalink to &quot;诚实的限制&quot;">​</a></h2><ul><li><strong>一定要看 diff 和成品文件。</strong> 看起来对 ≠ 正确。</li><li><strong><code>danger-full-access</code> 名副其实。</strong> 没读过的仓库不要开。</li><li><strong>搜索默认走缓存。</strong> 查变动很快的库时加裸 <code>--search</code>。</li><li><strong>Sites 的部署 URL 就是生产。</strong> 先 save version。</li><li><strong>版本会漂。</strong> 稳定版大约每周一个 minor。和 <code>learn.chatgpt.com/docs</code> 冲突时以官方为准。</li></ul><h2 id="和同类工具比" tabindex="-1">和同类工具比 <a class="header-anchor" href="#和同类工具比" aria-label="Permalink to &quot;和同类工具比&quot;">​</a></h2><table tabindex="0"><thead><tr><th>如果你要</th><th>考虑</th></tr></thead><tbody><tr><td>OpenAI 套餐上的终端 / 云端 Agent</td><td><strong>Codex</strong></td></tr><tr><td>同一套餐上的知识工作代理</td><td><a href="./chatgpt-work.html">ChatGPT Work</a></td></tr><tr><td>Anthropic 套餐上的对应全家桶</td><td><a href="./../claude/">Claude Code 生态</a></td></tr><tr><td>围绕 AI 做的编辑器</td><td><a href="./../cursor.html">Cursor</a></td></tr><tr><td>现有编辑器里的行内补全</td><td><a href="./../copilot.html">GitHub Copilot</a></td></tr></tbody></table><h2 id="官方来源" tabindex="-1">官方来源 <a class="header-anchor" href="#官方来源" aria-label="Permalink to &quot;官方来源&quot;">​</a></h2><table tabindex="0"><thead><tr><th>来源</th><th>用来查什么</th></tr></thead><tbody><tr><td><a href="https://learn.chatgpt.com/docs" target="_blank" rel="noreferrer">Codex 文档根</a></td><td>一切</td></tr><tr><td><a href="https://learn.chatgpt.com/docs/use-chatgpt" target="_blank" rel="noreferrer">Use ChatGPT</a></td><td>Chat / Work / Codex 怎么选</td></tr><tr><td><a href="https://learn.chatgpt.com/docs/get-started-with-work" target="_blank" rel="noreferrer">Get started with Work</a></td><td>Work</td></tr><tr><td><a href="https://learn.chatgpt.com/docs/cloud" target="_blank" rel="noreferrer">Codex cloud</a> · <a href="https://learn.chatgpt.com/codex/cloud" target="_blank" rel="noreferrer">落地页</a></td><td>托管编程环境</td></tr><tr><td><a href="https://learn.chatgpt.com/codex/ide" target="_blank" rel="noreferrer">IDE</a> · <a href="https://learn.chatgpt.com/codex/remote" target="_blank" rel="noreferrer">Remote</a></td><td>编辑器入口；手机控制</td></tr><tr><td><a href="https://learn.chatgpt.com/codex/security" target="_blank" rel="noreferrer">Security</a> · <a href="https://learn.chatgpt.com/codex/sites" target="_blank" rel="noreferrer">Sites</a> · <a href="https://learn.chatgpt.com/codex/chrome-extension" target="_blank" rel="noreferrer">Chrome</a></td><td>独立产品落地页</td></tr><tr><td><a href="https://learn.chatgpt.com/docs/whats-new" target="_blank" rel="noreferrer">What&#39;s new</a></td><td>周报级能力变化</td></tr><tr><td><a href="https://learn.chatgpt.com/docs/pricing" target="_blank" rel="noreferrer">Pricing</a></td><td>套餐和配额的唯一权威</td></tr><tr><td><a href="https://help.openai.com/en/articles/20001371-evolving-atlas-into-chatgpt-for-browser-based-agentic-work" target="_blank" rel="noreferrer">Atlas 演进说明</a></td><td>Atlas 下线（官方）</td></tr><tr><td><a href="https://github.com/openai/codex" target="_blank" rel="noreferrer">openai/codex</a></td><td>源码与发行版</td></tr></tbody></table><blockquote><p>文档页带 <code>?surface=cli|app|ide</code>。页面像在讲另一个产品时，先看当前 surface。</p></blockquote>`,49)])])}const f=a(o,[["render",n]]);export{x as __pageData,f as default};
